"use strict";(function(){function p(t){let e=(n,...i)=>l(o(t,n),n,...i).join("");return e.asArray=(n,...i)=>l(o(t,n),...i),e}function s(t){let e=(...n)=>l(t,...n).join("");return e.asArray=(...n)=>l(t,...n),e}function o(t,e){return t[i18n.quantity(e)]||t.other||t.one||""}function l(t,...e){let n=t.split(/(%(?:\d\$)?s)/);if(e.length){let i=n.indexOf("%s");if(i!=-1)n[i]=e[0];else for(let r=0;r<e.length;r++){let f=n.indexOf("%"+(r+1)+"$s");f!=-1&&(n[f]=e[r])}}return n}
let i=window.i18n.puzzleTheme={};i['advancedPawn']="Sumulong na pawn";i['advancedPawnDescription']="Isa sa iyong pawn ay malalim na sa posisyon ng kalaban, maaaring magbanta ng promosyon.";i['advantage']="Lamang";i['advantageDescription']="Kunin mo ang pagkakataon mo upang makukuha ng malaking bentahe. (200cp ≤ eval ≤ 600cp)";i['anastasiaMate']="Mate ni Anastasia";i['anastasiaMateDescription']="Isang kabayo at rook o reyna ay nagtutulungan upang bitagin ang kalabang hari sa pagitan ng gilid ng board at isang kaibigang piraso.";i['arabianMate']="Arabian mate";i['arabianMateDescription']="Isang kabayo at isang rook ay nagtutulungan upang bitagin ang kalabang hari sa isang sulok ng board.";i['attackingF2F7']="Pag-atake sa f2 o f7";i['attackingF2F7Description']="Isang atake na nakatuong sa f2 o f7 pawn, tulad ng sa pagbubukas ng fried liver.";i['attraction']="Atraksyon";i['attractionDescription']="An exchange or sacrifice encouraging or forcing an opponent piece to a square that allows a follow-up tactic.";i['backRankMate']="Back rank mate";i['backRankMateDescription']="Checkmate the king on the home rank, when it is trapped there by its own pieces.";i['balestraMate']="Balestra mate";i['balestraMateDescription']="A bishop delivers the checkmate, while a queen blocks the remaining escape squares";i['bishopEndgame']="Bishop endgame";i['bishopEndgameDescription']="An endgame with only bishops and pawns.";i['blindSwineMate']="Blind Swine mate";i['blindSwineMateDescription']="Two rooks team up to mate the king in an area of 2 by 2 squares.";i['bodenMate']="Mate ni Boden";i['bodenMateDescription']="Dalawang umaatakeng bishop sa mga pagtawid-tawid na pahalang ay nagdadala ng mate sa hari na hinaharangan ng mga kaibigang piraso.";i['capturingDefender']="Kunin ang tagapagtanggol";i['capturingDefenderDescription']="Removing a piece that is critical to defence of another piece, allowing the now undefended piece to be captured on a following move.";i['castling']="Castling";i['castlingDescription']="Dalhin ang hari sa kaligtasan, at ilabas ang rook upang umatake.";i['clearance']="Clearance";i['clearanceDescription']="A move, often with tempo, that clears a square, file or diagonal for a follow-up tactical idea.";i['collinearMove']="Collinear move";i['collinearMoveDescription']="Two opposing pieces face each other, and one slides along the line of attack without capturing the enemy piece.";i['cornerMate']="Corner mate";i['cornerMateKnightDeliversDescription']="Confine the king to the corner using a rook or queen, and use a knight to deliver the checkmate.";i['crushing']="Pagdurog";i['crushingDescription']="Makita ang malaking pagkakamali ng kalaban upang makakuha ng pagdurog na bentahe. (eval ≥ 600cp)";i['defensiveMove']="Depensibong galaw";i['defensiveMoveDescription']="A precise move or sequence of moves that is needed to avoid losing material or another advantage.";i['deflection']="Deflection";i['deflectionDescription']="A move that distracts an opposing piece from another duty that it performs, such as guarding a key square. Sometimes also called \"overloading\".";i['discoveredAttack']="Diskubreng atake";i['discoveredAttackDescription']="Moving a piece (such as a knight), that previously blocked an attack by a long range piece (such as a rook), out of the way of that piece.";i['discoveredCheck']="Discovered check";i['discoveredCheckDescription']="Move a piece to reveal a check from a hidden attacking piece, which often leads to a decisive advantage.";i['doubleBishopMate']="Dobleng bishop mate";i['doubleBishopMateDescription']="Dalawang umaatakeng bishop sa katabing mga pahalang ay nagdadala ng mate sa hari na hinaharangan ng mga kaibigang piraso.";i['doubleCheck']="Dobleng check";i['doubleCheckDescription']="Checking with two pieces at once, as a result of a discovered attack where both the moving piece and the unveiled piece attack the opponent's king.";i['dovetailMate']="Mate ni Cozio";i['dovetailMateDescription']="A queen delivers mate to an adjacent king, whose only two escape squares are obstructed by friendly pieces.";i['endgame']="Endgame";i['endgameDescription']="Isang taktika sa huling yugto ng laro.";i['enPassantAdjacentCaptureDescription']="A tactic involving the en passant rule, where a pawn can capture an opposing pawn that has just moved next to it with its initial two-square move.";i['epauletteMate']="Epaulette mate";i['epauletteMateDescription']="Two adjacent escape squares for a checked king are occupied by other pieces.";i['equality']="Pantay";i['equalityDescription']="Bumalik mula sa isang pagkatalo na posisyon, at makakuha ng isang tabla o isang balanseng posisyon. (eval ≤ 200cp)";i['exposedKing']="Nakalantad na hari";i['exposedKingDescription']="Isang taktika na kinasasangkutan ng isang hari na may ilang mga tagapagtanggol sa paligid nito, madalas na humahantong sa checkmate.";i['fork']="Taktika ng fork";i['forkOpposingPiecesDescription']="A move where a piece attacks two or more opposing pieces simultaneously.";i['hangingPiece']="Nakabitin na piraso";i['hangingPieceDescription']="A tactic involving an opponent piece being undefended or insufficiently defended and free to capture.";i['hookMate']="Hook mate";i['hookMateOpposingPawnDescription']="Checkmate using a rook, knight, and pawn, where an opposing pawn blocks the king's escape.";i['interference']="Interference";i['interferenceDescription']="Moving a piece between two opponent pieces to leave one or both opponent pieces undefended, such as a knight on a defended square between two rooks.";i['intermezzo']="Intermezzo";i['intermezzoDescription']="Instead of playing the expected move, first interpose another move posing an immediate threat that the opponent must answer. Also known as \"Zwischenzug\" or \"In between\".";i['killBoxMate']="Kill box mate";i['killBoxMateDescription']="A rook is next to the enemy king and supported by a queen that also blocks the king's escape squares. The rook and the queen catch the enemy king in a 3 by 3 \"kill box\".";i['kingsideAttack']="Panig na hari na atake";i['kingsideAttackDescription']="Isang atake ng kalabang hari, pagkatapos nilang mag-kastilyo sa panig na hari.";i['knightEndgame']="Knight endgame";i['knightEndgameDescription']="An endgame with only knights and pawns.";i['long']="Mahabang palaisipan";i['longDescription']="Tatlong galaw para manalo.";i['master']="Master games";i['masterDescription']="Mga palaisipan mula sa mga laro na nilalaro ng mga titulong manlalaro.";i['masterVsMaster']="Master vs Master games";i['masterVsMasterDescription']="Mga palaisipan mula sa mga laro na nilalaro sa pagitan ng dalawang titulong manlalaro.";i['mate']="Checkmate";i['mateDescription']="Manalo ang laro na may istilo.";i['mateIn1']="Mag-mate sa 1";i['mateIn1Description']="Magbigay ng checkmate sa isang tira.";i['mateIn2']="Mag-mate sa 2";i['mateIn2Description']="Magbigay ng checkmate sa dalawang tira.";i['mateIn3']="Mag-mate sa 3";i['mateIn3Description']="Magbigay ng checkmate sa tatlong tira.";i['mateIn4']="Mag-mate sa 4";i['mateIn4Description']="Magbigay ng checkmate sa apat na tira.";i['mateIn5']="Mag-mate sa 5 o higit pa";i['mateIn5Description']="Figure out a long mating sequence.";i['middlegame']="Middlegame";i['middlegameDescription']="Isang taktika sa ikalawang yugto ng laro.";i['mix']="Malusog na halo";i['mixDescription']="Kaunting sa lahat. Hindi mo alam kung ano ang aasahan, kaya laging handa ka sa anumang bagay! Tulad sa mga totoong laro.";i['morphyMateBishopAndRookDescription']="A bishop delivers checkmate to the king, while a rook helps confine it.";i['morphysMate']="Morphy's mate";i['oneMove']="Isang galaw na palaisipan";i['oneMoveDescription']="Isang palaisipan na isang galaw lang ang haba.";i['opening']="Pagbubukas";i['openingDescription']="Isang taktika sa unang yugto ng laro.";i['operaMate']="Opera mate";i['operaMateDescription']="Check the king with a rook and use a bishop to defend the rook.";i['pawnEndgame']="Pawn endgame";i['pawnEndgameDescription']="An endgame with only pawns.";i['pillsburyMateRookAndBishopDescription']="A rook delivers checkmate to the king, while a bishop helps confine it.";i['pillsburysMate']="Pillsbury's mate";i['pin']="Pin";i['pinDescription']="A tactic involving pins, where a piece is unable to move without revealing an attack on a higher value piece.";i['playerGames']="Mga laro ng manlalaro";i['playerGamesDescription']="Mga palaisipan na nabuo sa iyong mga laro, o mula sa mga laro ng ibang manlalaro.";i['promotePawnToQueenRookOrMinor']="Promote one of your pawns to a queen, rook or minor piece.";i['promotion']="Promosyon";i['puzzleDownloadInformation']=s("Ang mga palaisipan na ito ay nasa pampublikong domain, at maaaring i-download mula sa %s.");i['queenEndgame']="Queen endgame";i['queenEndgameDescription']="An endgame with only queens and pawns.";i['queenRookEndgame']="Reyna at Rook";i['queenRookEndgameDescription']="An endgame with only queens, rooks and pawns.";i['queensideAttack']="Panig na reyna na atake";i['queensideAttackDescription']="Isang atake ng kalabang hari, pagkatapos nilang mag-kastilyo sa panig na reyna.";i['quietMove']="Tahimik na galaw";i['quietMoveDescription']="A move that does not check, capture, or create an immediate threat to capture. Instead, it prepares a hidden and unavoidable threat for a later move.";i['rookEndgame']="Rook endgame";i['rookEndgameDescription']="An endgame with only rooks and pawns.";i['sacrifice']="Sakripisyo";i['sacrificeDescription']="Isang taktika na kinasasangkutan ang pagsuko ng materyal sa maikling panahon, para makakuha ng bentahe ulit pagkatapos ng sapilitang pagkakasunod-sunod ng mga galaw.";i['short']="Maikling palaisipan";i['shortDescription']="Dalawang galaw para manalo.";i['skewer']="Tuhog";i['skewerDescription']="A motif involving a high value piece being attacked, moving out the way, and allowing a lower value piece behind it to be captured or attacked, the inverse of a pin.";i['smotheredMate']="Smothered mate";i['smotheredMateDescription']="A checkmate delivered by a knight in which the mated king is unable to move because it is surrounded (or smothered) by its own pieces.";i['superGM']="Super GM games";i['superGMDescription']="Mga palaisipan mula sa mga laro na nilalaro ng mga pinakamahusay na manlalaro sa mundo.";i['swallowstailMate']="Swallow's tail mate";i['swallowstailMateDescription']="A checkmate pattern that visually resembles the appearance of a swallow’s tail, similar to a V shape.";i['trappedPiece']="Nakulong na piraso";i['trappedPieceDescription']="Ang isang piraso ay hindi makatakas sa pagkuha dahil limitado ang mga galaw nito.";i['triangleMate']="Triangle mate";i['triangleMateDescription']="The queen and rook, one square away from the enemy king, are on the same rank or file, separated by one square, forming a triangle.";i['underPromotion']="Underpromotion";i['underPromotionDescription']="Promosyon sa isang kabayo, bishop, o rook.";i['veryLong']="Napakahabang palaisipan";i['veryLongDescription']="Apat na galaw o higit pa para manalo.";i['vukovicMate']="Vuković mate";i['vukovicMateDescription']="A rook and knight team up to mate the king. The rook delivers mate while supported by a third piece, and the knight is used to block the king's escape squares.";i['xRayAttack']="Eksrey na atake";i['xRayAttackDescription']="A piece attacks or defends a square, through an enemy piece.";i['zugzwang']="Zugzwang";i['zugzwangDescription']="Ang kalaban ay limitado sa mga galaw na maaari nilang gawin, at lahat ng galaw ay lumala sa kanilang posisyon.";i['enPassantDescription']="Isang taktika na kinasasangkutan ng en passant na panuntunan, kung saan ang isang pawn ay maaaring makuha ang isang pawn ng kalaban na na-bypass ito gamit ang paunang dalawang-parisukat na paglipat.";i['forkDescription']="Isang paglipat kung saan inaatake ng inilipat na piraso ang dalawang piraso ng kalaban nang sabay-sabay."})()